    private final ByteBuffer data;
    private final int[] offsets = new int[32];
    private final int[] sizeBits = new int[32];

    private Dictionary() {
        ByteBuffer dictionaryData = ByteBuffer.allocate(122784);
        int[] dictionarySizeBits = new int[25];
        unpackDictionaryData(dictionaryData, dictionarySizeBits);
        dictionaryData = dictionaryData.flip().asReadOnlyBuffer();
        data = setData(dictionaryData, dictionarySizeBits);
    }

    static Dictionary instance() {
        return LazyHolder.INSTANCE;
    }

    int offset(int length) {
        return offsets[length];
    }

    int sizeBits(int length) {
        return sizeBits[length];
    }

    ByteBuffer data() {
        // Shared by all decoders; only absolute reads may be used.
        return data;
    }

    private ByteBuffer setData(ByteBuffer newData, int[] newSizeBits) {
        int minDictionaryWordLength = 4;
        if (!newData.isReadOnly()) {
            throw new BrotliException("newData must be a read-only byte buffer");
        }
        if (newSizeBits.length > MAX_DICTIONARY_WORD_LENGTH) {
            throw new BrotliException("sizeBits length must be at most " + MAX_DICTIONARY_WORD_LENGTH);
        }
        for (int i = 0; i < minDictionaryWordLength; ++i) {
            if (newSizeBits[i] != 0) {
                throw new BrotliException("first " + minDictionaryWordLength + " must be 0");
            }
        }
        System.arraycopy(newSizeBits, 0, sizeBits, 0, newSizeBits.length);
        int pos = 0;
        int limit = newData.capacity();
        for (int i = 0; i < newSizeBits.length; ++i) {
            offsets[i] = pos;
            int bits = sizeBits[i];
            if (bits != 0) {
                if (bits >= 31) {
                    throw new BrotliException("newSizeBits values must be less than 31");
                }
                pos += i << bits;
                if (pos <= 0 || pos > limit) {
                    throw new BrotliException("newSizeBits is inconsistent: overflow");
                }
            }
        }
        for (int i = newSizeBits.length; i < 32; ++i) {
            offsets[i] = pos;
        }
        if (pos != limit) {
            throw new BrotliException("newSizeBits is inconsistent: underflow");
        }
        return newData;
    }

    private void unpackDictionaryData(ByteBuffer dictionary, int[] sizeBits) {
        byte[] dict = mergeArrays(toUsAsciiBytes(DATA0), toUsAsciiBytes(DATA1));
        if (dict.length != dictionary.capacity()) {
            throw new BrotliException("Corrupted brotli dictionary");
        }

        int offset = 0;
        int n = SKIP_FLIP.length();
        for (int i = 0; i < n; i += 2) {
            int skip = SKIP_FLIP.charAt(i) - 36;
            int flip = SKIP_FLIP.charAt(i + 1) - 36;
            for (int j = 0; j < skip; ++j) {
                dict[offset] ^= 3;
                offset++;
            }
            for (int j = 0; j < flip; ++j) {
                dict[offset] ^= 236;
                offset++;
            }
        }

        String sizeBitsData = "AAAAKKLLKKKKKJJIHHIHHGGFF";
        for (int i = 0; i < sizeBitsData.length(); ++i) {
            sizeBits[i] = sizeBitsData.charAt(i) - 65;
        }
        dictionary.put(dict);
    }

    private byte[] toUsAsciiBytes(String src) {
        return src.getBytes(StandardCharsets.US_ASCII);
    }

